  async invite(communityId: string, member: NodeId, roleIds: readonly string[] = [], reason?: string): Promise<CommunityMemberObject> { const projection = await this.requireProjection(communityId); await this.requireAnyPermission(projection, this.local.nodeId, ['invite_members', 'manage_members']); ensureAssignableRoles(projection, this.local.nodeId, roleIds); return this.publishMember(communityId, member, 'invite', roleIds, reason); }
