  async setNotificationSettings(communityId: string, settings: Partial<CommunityNotificationSettings>): Promise<CommunityNotificationSettings> { const current = await this.notificationSettings(communityId); const next = { muted: settings.muted ?? current.muted, mutedCategories: [...new Set(settings.mutedCategories ?? current.mutedCategories)], mutedChannels: [...new Set(settings.mutedChannels ?? current.mutedChannels)] }; await this.storage.saveNotificationSettings(communityId, next); return next; }
  async notificationSettings(communityId: string): Promise<CommunityNotificationSettings> { return (await this.storage.getNotificationSettings(communityId)) ?? { muted: false, mutedCategories: [], mutedChannels: [] }; }
  async block(identity: NodeId): Promise<void> { await this.storage.setBlocked(identity, true); }
  async unblock(identity: NodeId): Promise<void> { await this.storage.setBlocked(identity, false); }
  async mute(identity: NodeId): Promise<void> { await this.storage.setMuted(identity, true); }
  async unmute(identity: NodeId): Promise<void> { await this.storage.setMuted(identity, false); }
  async report(communityId: string, targetObjectId: string, reason: string, targetAuthor?: NodeId): Promise<CommunityReportObject> { await this.requireProjection(communityId); const unsigned = { version: KEYSTONE_OBJECT_VERSION as 1, type: 'community_report' as const, id: crypto.randomUUID(), author: this.local.nodeId, createdAt: this.date(), visibility: 'community' as const, references: [{ id: communityId, type: 'community' as const }, { id: targetObjectId, type: 'community_message' as const }], payload: { communityId, targetObjectId, ...(targetAuthor ? { targetAuthor } : {}), reason: reason.trim(), createdAt: this.date() } }; const object = communityReportObjectSchema.parse({ ...unsigned, signature: await this.sign(unsigned) }); await this.storage.save(object); return object; }

